# ruff: noqa: E501

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(include_in_schema=False)


@router.get("/campgrounds", response_class=HTMLResponse)
async def campgrounds_page() -> HTMLResponse:
    return HTMLResponse(
        """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RoadTalk | Campgrounds</title><style>:root{color-scheme:dark}body{margin:auto;max-width:1050px;padding:24px;background:#07141b;color:#f2f7f9;font-family:system-ui}nav,.filters{display:flex;gap:12px;flex-wrap:wrap}.panel,.card{border:1px solid #45606b;background:#10232e;border-radius:14px;padding:16px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}.filters>*{flex:1;min-width:180px}input,select,button{width:100%;padding:10px;background:#07141b;color:#fff;border:1px solid #78909a;border-radius:8px}:focus-visible{outline:3px solid #f2b84b;outline-offset:3px}.muted{color:#abc0c9}</style></head><body><nav aria-label="RoadTalk"><strong>RoadTalk Campgrounds</strong><a href="/">Web Radio</a><a href="/map">Map</a><a href="/campgrounds" aria-current="page">Campgrounds</a><a href="/audience">Audience</a></nav><main><h1>Campground discovery, without campground tracking.</h1><p class="muted">Deterministic test catalog only — not a live or complete directory. No reservations, booking, payments, campsite occupancy, or member lists.</p><section class="panel"><h2>Current campground context</h2><p id="context" role="status" aria-live="polite">Current context is shown only when RoadTalk can derive it from authorized current state. Browsing or selecting a campground never grants communication access.</p><a href="/">Open Web Radio to establish your signed-in current session</a></section><section class="filters" aria-label="Campground filters"><label>Search<input id="q" type="search" placeholder="Name or locality"></label><label>Category<select id="cat"><option value="">All</option><option value="public">Public</option><option value="state_park">State park</option><option value="private">Private</option></select></label><label>Amenity<select id="amenity"><option value="">Any</option><option value="electric">Electric</option><option value="water">Water</option><option value="sewer">Sewer</option><option value="wifi">Wi-Fi</option><option value="showers">Showers</option><option value="laundry">Laundry</option><option value="pet_friendly">Pet friendly</option></select></label></section><p id="status" role="status" aria-live="polite"></p><section id="results" class="grid" aria-label="Campground results"></section></main><script>const s={rows:[]},$=x=>document.getElementById(x);function render(){const q=$('q').value.toLowerCase(),c=$('cat').value,a=$('amenity').value,rows=s.rows.filter(x=>(!q||x.name.toLowerCase().includes(q)||x.locality.toLowerCase().includes(q))&&(!c||x.category===c)&&(!a||x.amenities[a]));$('results').replaceChildren(...rows.map(x=>{const e=document.createElement('article');e.className='card';const h=document.createElement('h2');h.textContent=x.name;const p=document.createElement('p');p.textContent=x.locality+', '+x.region+' · '+x.category.replaceAll('_',' ');const n=document.createElement('p');n.className='muted';n.textContent='Deterministic test data · campground centroid metadata · not live availability';e.append(h,p,n);return e}));$('status').textContent=rows.length+' deterministic test campground(s) shown.'}fetch('/api/v1/campgrounds/catalog',{headers:{Accept:'application/json'}}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{if(d.live_directory!==false||d.source!=='deterministic_local')throw Error();s.rows=d.campgrounds;render()}).catch(()=>{$('status').textContent='Campground test catalog is unavailable.'});['q','cat','amenity'].forEach(id=>$(id).addEventListener('input',render));</script></body></html>"""
    )
